function renderGrid(){
  const grid=document.getElementById('grid');
  grid.innerHTML=posts.map(p=>`<div class="grid-item" onclick="openPost(${p.id})"><img src="${p.img}"><div class="overlay">❤ ${p.likes} 💬 ${p.comments.length}</div></div>`).join('');
}
function openPost(id){
  const p=posts.find(x=>x.id===id);
  document.getElementById('modal-img').src=p.img;
  document.getElementById('modal-title').innerText=p.title;
  document.getElementById('modal-desc').innerText=p.desc;
  document.getElementById('modal-likes').innerText=p.likes;
  document.getElementById('modal-comments').innerHTML=p.comments.map(c=>`<div class="comment"><b>${c.user}</b> ${c.text}</div>`).join('');
  document.getElementById('modal').classList.add('active');
}
function closeModal(){document.getElementById('modal').classList.remove('active');}
function openFriend(name){alert(name+" - Em breve perfil completo de "+name+"!");}
document.getElementById('modal').addEventListener('click',(e)=>{if(e.target.id==='modal') closeModal();});
renderGrid();